using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace CoastalFactory.Editor {public static partial class LeftFactoryDistrictBuilder {
[Serializable]public class CentreRoute {public string name;public float width;public Vector2[] points;}
[Serializable]public class CentreRoutes {public CentreRoute[] routes;}
static int AlignTrafficToCentreLines(){var data=JsonUtility.FromJson<CentreRoutes>(File.ReadAllText("Tools/CentrelineRoads/rebuilt_routes.json"));var trucks=new List<GameObject>();var obstacles=new List<Bounds>();foreach(var t in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None)){if(!PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject))continue;string path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(!path.Contains("Art/Environment/Assets/"))continue;if(path.Contains("SteelTruck/")||path.Contains("ScrapDumpTruck/"))trucks.Add(t.gameObject);else obstacles.Add(B(t.gameObject));}int moved=0;foreach(var truck in trucks){var oldBounds=B(truck);var oldPos=truck.transform.position;var oldRot=truck.transform.rotation;float best=float.PositiveInfinity;var bestPos=oldPos;var bestRot=oldRot;Bounds bestBounds=oldBounds;foreach(var route in data.routes){for(int i=0;i<route.points.Length-1;i++){var a=route.points[i];var b=route.points[i+1];var delta=b-a;if(delta.sqrMagnitude<.1f)continue;float fraction=Mathf.Clamp(Vector2.Dot(new Vector2(oldBounds.center.x,oldBounds.center.z)-a,delta)/delta.sqrMagnitude,.1f,.9f);var q=a+delta*fraction;for(int direction=-1;direction<=1;direction+=2){var forward=delta.normalized*direction;var right=new Vector2(forward.y,-forward.x);float offset=route.width>10?5.25f:1.75f;var p=q+right*offset;float score=Vector2.Distance(new Vector2(oldBounds.center.x,oldBounds.center.z),p);if(score>=best)continue;truck.transform.rotation=Quaternion.Euler(0,Mathf.Atan2(forward.x,forward.y)*Mathf.Rad2Deg,0);var bb=B(truck);truck.transform.position+=new Vector3(p.x-bb.center.x,.05f-bb.min.y,p.y-bb.center.z);bb=B(truck);bool clear=true;foreach(var block in obstacles)if(bb.min.x<block.max.x+.5f&&bb.max.x>block.min.x-.5f&&bb.min.z<block.max.z+.5f&&bb.max.z>block.min.z-.5f){clear=false;break;}if(!clear)continue;best=score;bestPos=truck.transform.position;bestRot=truck.transform.rotation;bestBounds=bb;}}}if(float.IsInfinity(best))throw new Exception("No new lane location for "+truck.name);truck.transform.SetPositionAndRotation(bestPos,bestRot);obstacles.Add(bestBounds);moved++;}Debug.Log("CENTRELINE_TRAFFIC_PASS count="+moved);return moved;}
[MenuItem("Anseong/Art/Rebuild Roads From Centre Lines")]public static void RebuildRoadsFromCentreLines(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/CentrelineRoads";Folder(folder);if(GameObject.Find("Roads_CentrelineRebuilt"))throw new Exception("Already rebuilt");var result=JsonUtility.FromJson<RoadResult>(File.ReadAllText("Tools/CentrelineRoads/road_union_result.json"));var mesh=new Mesh{name="UnifiedSmoothRoadSurface",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};var vertices=new List<Vector3>();var indices=new List<int>[3];for(int c=0;c<3;c++)indices[c]=new List<int>();foreach(var layer in result.layers){for(int i=0;i<layer.xy.Length;i+=6){int start=vertices.Count;float y=layer.channel==0?.038f:layer.channel==1?.052f:.054f;for(int k=0;k<3;k++)vertices.Add(new Vector3(layer.xy[i+k*2],y,layer.xy[i+k*2+1]));indices[layer.channel].AddRange(new[]{start,start+2,start+1});}}mesh.SetVertices(vertices);mesh.subMeshCount=3;for(int c=0;c<3;c++)mesh.SetTriangles(indices[c],c);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/UnifiedRoadSurface.asset");var g=new GameObject("Roads_CentrelineRebuilt");g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterials=new[]{AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/Asphalt.mat"),AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/RoadWhite.mat"),AssetDatabase.LoadAssetAtPath<Material>("Assets/_Anseong/Art/Environment/GroundRoadsV2/CentreYellow.mat")};foreach(var name in new[]{"GroundRoadNetwork","FactoryRoads_RetainedToRearBoundary","Roads_UnifiedSmoothSurface"}){var oldRoad=GameObject.Find(name);if(oldRoad)oldRoad.SetActive(false);}int aligned=AlignTrafficToCentreLines();File.WriteAllText(folder+"/VerificationReport.md",result.report);AssetDatabase.Refresh();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"CentrelineRoads_Main");var go=new GameObject("RoadJunctionPreview");var cam=go.AddComponent<Camera>();cam.CopyFrom(Camera.main);cam.transform.position=new Vector3(-210,110,330);cam.transform.LookAt(new Vector3(-240,0,405));Capture(cam,"CentrelineRoads_Junction");cam.transform.position=new Vector3(-350,300,750);cam.transform.LookAt(new Vector3(-400,0,650));Capture(cam,"CentrelineRoads_Factory");Object.DestroyImmediate(go);Debug.Log("UNIFIED_ROADS_PASS vertices="+vertices.Count+" buildingsUnchanged=true");}

}}